<?php require_role('admin');$pageTitle='Project Register';$pageSubtitle='Central record of topics, stages and supervision activity';$rows=db_all("SELECT p.*,st.full_name student_name,st.matric_no,sp.full_name supervisor_name,(SELECT COUNT(*) FROM sessions s WHERE s.project_id=p.id AND s.status='completed') completed_sessions,(SELECT COUNT(*) FROM documents d WHERE d.project_id=p.id) documents FROM projects p JOIN users st ON st.id=p.student_id LEFT JOIN users sp ON sp.id=p.supervisor_id ORDER BY st.full_name");include __DIR__.'/../includes/layout_top.php'; ?>
<div class="card"><div class="card-header"><div><h2>Departmental project register</h2><p>Use this view for supervision compliance and project monitoring.</p></div></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Topic</th><th>Supervisor</th><th>Stage</th><th>Sessions</th><th>Documents</th><th>Progress</th></tr></thead><tbody><?php foreach($rows as $r):$prog=progress_for_project((int)$r['id']);?><tr><td><strong><?= e($r['student_name']) ?></strong><br><?= e($r['matric_no']) ?></td><td><?= e($r['title']) ?></td><td><?= e($r['supervisor_name']?:'Unassigned') ?></td><td><span class="badge warning"><?= e($r['current_stage']) ?></span></td><td><?= (int)$r['completed_sessions'] ?></td><td><?= (int)$r['documents'] ?></td><td><?= $prog ?>%</td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/layout_bottom.php'; ?>
